 let hold=null,suppressClick=null;
 function cancelHold(){if(hold){window.clearTimeout(hold.timer);hold=null;}}
 root.addEventListener('pointerdown',e=>{cancelHold();const row=e.target.closest('.mail-row');if(!row||e.button!==0||e.isPrimary===false)return;const ref={folder:mailFolder,uid:row.dataset.id,validity:row.dataset.validity};hold={ref,x:e.clientX,y:e.clientY,pointer:e.pointerId,timer:window.setTimeout(()=>{hold=null;if(!row.isConnected||route!=='mail'||selected||form)return;suppressClick={key:uidKey(ref),at:Date.now()};openLabelMenu(row);},550)};});
