 function applyTheme(){document.documentElement.dataset.theme=local.settings.theme||'system';document.documentElement.dataset.system=(typeof Pilot.systemDark==='function'?Pilot.systemDark():window.matchMedia?.('(prefers-color-scheme: dark)').matches)?'dark':'light';}
 window.systemThemeChanged=applyTheme;window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',applyTheme);
