 window.appBack=()=>{if(labelTarget||assistText!==null||templatePopup){closeQuick();return;}if(dayPopup&&!form){closeDay();return;}if(sendBusy){say('Дождитесь результата отправки.');return;}if(!keepDraft())return;if(form){form=null;draft=null;}else if(selected){selected=null;}else{route='mail';}root.querySelector('.folder-menu').open=false;render();};
