  if(action==='quick-file'){const [folder,uid,validity,path]=JSON.parse(key);say('Скачивание в Загрузки…');request('quickDownload',[folder,uid,validity,path],result=>say(result.error||(result.cancelled?'Сохранение отменено.':result.downloads?'Файл сохранён в Загрузки / Рабочая почта.':result.saved?'Файл сохранён в выбранное место.':'Выберите место сохранения.')));return;}
